     1→'use client'
     2→
     3→import { useState, useCallback } from 'react'
     4→import {
     5→  DndContext,
     6→  DragOverlay,
     7→  closestCorners,
     8→  KeyboardSensor,
     9→  PointerSensor,
    10→  useSensor,
    11→  useSensors,
    12→  type DragStartEvent,
    13→  type DragEndEvent,
    14→} from '@dnd-kit/core'
    15→import { sortableKeyboardCoordinates } from '@dnd-kit/sortable'
    16→import type { Task, WorkLog, TaskStatus } from '@/types'
    17→import { KanbanColumn } from './KanbanColumn'
    18→import { TaskCard } from './TaskCard'
    19→import { TaskModal } from './TaskModal'
    20→import { AddTaskModal } from './AddTaskModal'
    21→
    22→interface KanbanBoardProps {
    23→  initialTasks: Task[]
    24→  initialWorkLogs: WorkLog[]
    25→}
    26→
    27→const columns: { status: TaskStatus; title: string }[] = [
    28→  { status: 'todo', title: 'Todo' },
    29→  { status: 'doing', title: 'Doing' },
    30→  { status: 'done', title: 'Done' },
    31→]
    32→
    33→export function KanbanBoard({ initialTasks, initialWorkLogs }: KanbanBoardProps) {
    34→  const [tasks, setTasks] = useState<Task[]>(initialTasks)
    35→  const [workLogs, setWorkLogs] = useState<WorkLog[]>(initialWorkLogs)
    36→  const [activeTask, setActiveTask] = useState<Task | null>(null)
    37→  const [selectedTask, setSelectedTask] = useState<Task | null>(null)
    38→  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false)
    39→  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
    40→  const [addTaskStatus, setAddTaskStatus] = useState<TaskStatus>('todo')
    41→
    42→  const sensors = useSensors(
    43→    useSensor(PointerSensor, {
    44→      activationConstraint: {
    45→        distance: 8,
    46→      },
    47→    }),
    48→    useSensor(KeyboardSensor, {
    49→      coordinateGetter: sortableKeyboardCoordinates,
    50→    })
    51→  )
    52→
    53→  const getTasksByStatus = (status: TaskStatus) =>
    54→    tasks.filter((task) => task.status === status)
    55→
    56→  const handleDragStart = (event: DragStartEvent) => {
    57→    const task = tasks.find((t) => t.id === event.active.id)
    58→    if (task) {
    59→      setActiveTask(task)
    60→    }
    61→  }
    62→
    63→  const handleDragEnd = async (event: DragEndEvent) => {
    64→    const { active, over } = event
    65→    setActiveTask(null)
    66→
    67→    if (!over) return
    68→
    69→    const activeId = active.id as string
    70→    const overId = over.id as string
    71→
    72→    const activeTaskData = tasks.find((t) => t.id === activeId)
    73→    if (!activeTaskData) return
    74→
    75→    let newStatus: TaskStatus
    76→    let newPosition: number
    77→
    78→    const overTask = tasks.find((t) => t.id === overId)
    79→    if (overTask) {
    80→      newStatus = overTask.status
    81→      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
    82→      const overIndex = tasksInColumn.findIndex((t) => t.id === overId)
    83→      newPosition = overIndex
    84→    } else {
    85→      newStatus = overId as TaskStatus
    86→      const tasksInColumn = tasks.filter((t) => t.status === newStatus)
    87→      newPosition = tasksInColumn.length
    88→    }
    89→
    90→    if (activeTaskData.status === newStatus) {
    91→      const tasksInColumn = tasks
    92→        .filter((t) => t.status === newStatus)
    93→        .sort((a, b) => a.position - b.position)
    94→      const oldIndex = tasksInColumn.findIndex((t) => t.id === activeId)
    95→      if (oldIndex === newPosition) return
    96→    }
    97→
    98→    const updatedTasks = tasks.map((t) => {
    99→      if (t.id === activeId) {
   100→        return { ...t, status: newStatus, position: newPosition }
   101→      }
   102→      return t
   103→    })
   104→    setTasks(updatedTasks)
   105→
   106→    try {
   107→      const response = await fetch('/api/tasks/reorder', {
   108→        method: 'PUT',
   109→        headers: { 'Content-Type': 'application/json' },
   110→        body: JSON.stringify({
   111→          taskId: activeId,
   112→          newStatus,
   113→          newPosition,
   114→        }),
   115→      })
   116→
   117→      if (response.ok) {
   118→        const data = await response.json()
   119→        if (data.success) {
   120→          setTasks(data.data)
   121→        }
   122→      }
   123→    } catch {
   124→      setTasks(initialTasks)
   125→    }
   126→  }
   127→
   128→  const handleTaskClick = useCallback((task: Task) => {
   129→    setSelectedTask(task)
   130→    setIsTaskModalOpen(true)
   131→  }, [])
   132→
   133→  const handleAddTaskClick = useCallback((status: TaskStatus) => {
   134→    setAddTaskStatus(status)
   135→    setIsAddModalOpen(true)
   136→  }, [])
   137→
   138→  const handleAddTask = async (title: string, status: TaskStatus) => {
   139→    const response = await fetch('/api/tasks', {
   140→      method: 'POST',
   141→      headers: { 'Content-Type': 'application/json' },
   142→      body: JSON.stringify({ title, status }),
   143→    })
   144→
   145→    if (response.ok) {
   146→      const data = await response.json()
   147→      if (data.success) {
   148→        setTasks((prev) => [...prev, data.data])
   149→      }
   150→    }
   151→  }
   152→
   153→  const handleUpdateTask = async (updates: Partial<Task>) => {
   154→    if (!selectedTask) return
   155→
   156→    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
   157→      method: 'PUT',
   158→      headers: { 'Content-Type': 'application/json' },
   159→      body: JSON.stringify(updates),
   160→    })
   161→
   162→    if (response.ok) {
   163→      const data = await response.json()
   164→      if (data.success) {
   165→        setTasks((prev) =>
   166→          prev.map((t) => (t.id === selectedTask.id ? data.data : t))
   167→        )
   168→        setSelectedTask(data.data)
   169→      }
   170→    }
   171→  }
   172→
   173→  const handleDeleteTask = async () => {
   174→    if (!selectedTask) return
   175→
   176→    const response = await fetch(`/api/tasks/${selectedTask.id}`, {
   177→      method: 'DELETE',
   178→    })
   179→
   180→    if (response.ok) {
   181→      setTasks((prev) => prev.filter((t) => t.id !== selectedTask.id))
   182→      setWorkLogs((prev) => prev.filter((w) => w.taskId !== selectedTask.id))
   183→      setIsTaskModalOpen(false)
   184→      setSelectedTask(null)
   185→    }
   186→  }
   187→
   188→  const handleArchiveTask = async () => {
   189→    if (!selectedTask) return
   190→    await handleUpdateTask({ status: 'archived' })
   191→    setIsTaskModalOpen(false)
   192→    setSelectedTask(null)
   193→  }
   194→
   195→  const handleAddWorkLog = async (content: string) => {
   196→    if (!selectedTask) return
   197→
   198→    const response = await fetch('/api/worklogs', {
   199→      method: 'POST',
   200→      headers: { 'Content-Type': 'application/json' },
   201→      body: JSON.stringify({
   202→        taskId: selectedTask.id,
   203→        content,
   204→      }),
   205→    })
   206→
   207→    if (response.ok) {
   208→      const data = await response.json()
   209→      if (data.success) {
   210→        setWorkLogs((prev) => [...prev, data.data])
   211→      }
   212→    }
   213→  }
   214→
   215→  const handleDeleteWorkLog = async (id: string) => {
   216→    const response = await fetch(`/api/worklogs/${id}`, {
   217→      method: 'DELETE',
   218→    })
   219→
   220→    if (response.ok) {
   221→      setWorkLogs((prev) => prev.filter((w) => w.id !== id))
   222→    }
   223→  }
   224→
   225→  const selectedTaskWorkLogs = selectedTask
   226→    ? workLogs.filter((w) => w.taskId === selectedTask.id)
   227→    : []
   228→
   229→  return (
   230→    <>
   231→      <DndContext
   232→        sensors={sensors}
   233→        collisionDetection={closestCorners}
   234→        onDragStart={handleDragStart}
   235→        onDragEnd={handleDragEnd}
   236→      >
   237→        <div className="flex gap-4 overflow-x-auto pb-4">
   238→          {columns.map(({ status, title }) => (
   239→            <KanbanColumn
   240→              key={status}
   241→              status={status}
   242→              title={title}
   243→              tasks={getTasksByStatus(status)}
   244→              workLogs={workLogs}
   245→              onTaskClick={handleTaskClick}
   246→              onAddTask={() => handleAddTaskClick(status)}
   247→            />
   248→          ))}
   249→        </div>
   250→        <DragOverlay>
   251→          {activeTask && (
   252→            <div className="opacity-80">
   253→              <TaskCard
   254→                task={activeTask}
   255→                onClick={() => {}}
   256→              />
   257→            </div>
   258→          )}
   259→        </DragOverlay>
   260→      </DndContext>
   261→
   262→      {selectedTask && (
   263→        <TaskModal
   264→          task={selectedTask}
   265→          workLogs={selectedTaskWorkLogs}
   266→          isOpen={isTaskModalOpen}
   267→          onClose={() => {
   268→            setIsTaskModalOpen(false)
   269→            setSelectedTask(null)
   270→          }}
   271→          onUpdate={handleUpdateTask}
   272→          onDelete={handleDeleteTask}
   273→          onArchive={handleArchiveTask}
   274→          onAddWorkLog={handleAddWorkLog}
   275→          onDeleteWorkLog={handleDeleteWorkLog}
   276→        />
   277→      )}
   278→
   279→      <AddTaskModal
   280→        isOpen={isAddModalOpen}
   281→        initialStatus={addTaskStatus}
   282→        onClose={() => setIsAddModalOpen(false)}
   283→        onSubmit={handleAddTask}
   284→      />
   285→    </>
   286→  )
   287→}
   288→

