     1→import { v4 as uuidv4 } from 'uuid'
     2→import { format } from 'date-fns'
     3→
     4→export function generateId(): string {
     5→  return uuidv4()
     6→}
     7→
     8→export function getCurrentDate(): string {
     9→  return format(new Date(), 'yyyy-MM-dd')
    10→}
    11→
    12→export function getCurrentTimestamp(): string {
    13→  return new Date().toISOString()
    14→}
    15→
    16→export function isOverdue(dueDate: string | null): boolean {
    17→  if (!dueDate) return false
    18→  const today = new Date()
    19→  today.setHours(0, 0, 0, 0)
    20→  const due = new Date(dueDate)
    21→  due.setHours(0, 0, 0, 0)
    22→  return due < today
    23→}
    24→
    25→export function formatDate(dateString: string): string {
    26→  return format(new Date(dateString), 'yyyy/MM/dd')
    27→}
    28→
    29→export function formatDateTime(dateString: string): string {
    30→  return format(new Date(dateString), 'yyyy/MM/dd HH:mm')
    31→}
    32→
    33→export function cn(...classes: (string | undefined | null | false)[]): string {
    34→  return classes.filter(Boolean).join(' ')
    35→}
